record AuthToken(string Subject, string Issuer, DateTimeOffset ExpiresAt)
{
    public bool IsExpired(DateTimeOffset now) => now >= ExpiresAt;
}

readonly record struct RedisEntry(string Key, int TtlSeconds);

var token = new AuthToken("user-9", "https://auth.example",
    DateTimeOffset.UtcNow.AddHours(1));
var refreshed = token with { ExpiresAt = DateTimeOffset.UtcNow.AddHours(8) };

Console.WriteLine(token == refreshed);       // False — different ExpiresAt
Console.WriteLine(token.Subject == refreshed.Subject); // True

record GradeEvent(string AttemptId, int Score, string Tenant);

var evt = new GradeEvent("a-42", 95, "acme");

// Generated ToString
Console.WriteLine(evt);
// GradeEvent { AttemptId = a-42, Score = 95, Tenant = acme }

// Generated Deconstruct
var (attemptId, score, tenant) = evt;
Console.WriteLine($"{tenant}/{attemptId}: {score}");

// Entity with identity — use a class
public sealed class Attempt
{
    public string Id { get; }
    public int Score { get; set; } // mutable state
    public Attempt(string id) => Id = id;
}

// Mutable record — legal but loses dictionary-key safety
public record MutableDto
{
    public string Key { get; set; } // setter breaks immutability
}

record AuthToken(string Subject, string Issuer, DateTimeOffset ExpiresAt);

var cache = new Dictionary<AuthToken, string>();
var original = new AuthToken("user-9", "https://auth.example",
    DateTimeOffset.UtcNow.AddHours(1));
cache[original] = "session-abc";

// Different heap object, same values — lookup must succeed
var lookup = new AuthToken(original.Subject, original.Issuer, original.ExpiresAt);
Console.WriteLine(cache[lookup]); // session-abc

// with creates a new unequal instance — correct miss
var refreshed = original with { ExpiresAt = DateTimeOffset.UtcNow.AddHours(8) };
Console.WriteLine(cache.ContainsKey(refreshed)); // False
